import{_ as a,a0 as l,w as u,s as r,ao as i,I as s,x as p,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"22 天遷移到公共雲 | LCTT x X-CMD","titleTemplate":false,"description":"22 天遷移到公共雲 | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"22 天遷移到公共雲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"22 天遷移到公共雲 | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20170310 A public cloud migration in 22 days","title":"22 天遷移到公共雲","tag":"201709","desc":""},"relativePath":"201709/20170310 A public cloud migration in 22 days.md","filePath":"[post].md"}'),d={name:"201709/20170310 A public cloud migration in 22 days.md"};function m(g,t,f,C,T,L){const o=l("Link");return u(),r("div",null,[t[16]||(t[16]=i('<h1 id="_22-天遷移到公共雲" tabindex="-1">22 天遷移到公共雲 <a class="header-anchor" href="#_22-天遷移到公共雲" aria-label="Permalink to “22 天遷移到公共雲”">​</a></h1><p><img src="https://i.nextmedia.com.au/Utils/ImageResizer.ashx?n=http%3a%2f%2fi.nextmedia.com.au%2fNews%2fLush.jpg&amp;w=480&amp;c=0&amp;s=1" alt="A public cloud migration in 22 days"></p><blockquote><p>Lush 説這是可能的。</p></blockquote><p>在不到一個月內將你的核心業務從一個公共雲遷移到另一個公共雲看起來像是一個遙不可及的目標，但是英國化妝品巨頭 Lush 認為可以做到這一點。</p><p>去年九月 Lush —— 你也許知道它是那些糖果色的、好聞的沐浴和護膚產品背後的公司 —— 與已有的基礎設施供應商 Acquia 的合同快要到期了。</p><p>Acquia 已經在 AWS 中託管了 Lush 的基於 Drupal 的電子商務環境好幾年了，但該零售商想要退出合作。</p><p>根據 Lush 的首席數字官及公司的繼承人 Jack Constantine（他的父母在 1995 年成立該公司）的説法，該安排是“尷尬”和僵硬的。</p><p>他今天在舊金山舉行的 Google Cloud Next 會議上説：“我們不太滿意那份合同，我們想看看我們還能做些什麼。”</p><p>“那是一個非常封閉的環境，這使我們難於看清下一步做什麼。”</p><p>“(我們) 可以再簽署一年，在此期間想出一個有更多的控制權的長期計劃，但是（我們）最終結束了這種掙扎。”</p>',10)),s("p",null,[t[1]||(t[1]=p("在淘遍市場後，Lush 目標放在 Google 的雲平台上。該公司已經很熟悉 Google 了，已於 ",-1)),e(o,{href:"https://cloud.googleblog.com/2013/12/google-apps-helps-eco-cosmetics-company.html"},{default:n(()=>[...t[0]||(t[0]=[p("2013 年底",-1)])]),_:1}),t[2]||(t[2]=p("從 Scalix 遷移到 Google Apps（現稱為 G Suite）上。",-1))]),t[17]||(t[17]=i("<p>然而，只有幾個月不到的時間進行遷移，要趕在 12 月 22 日現有合同截止前和聖誕節購物的關鍵時期前。</p><p>Constantine 説：“所以這不僅僅是有點關鍵的業務，我們要考慮高峯交易期，那時會有巨大的交易。”</p><p>Lush 擺脱了官僚主義意味着 Constantine 能夠在選擇供應商上快速決定。他説：“接着團隊只要全力進行就行。”</p><p>他們還為這次遷移專門優先優化了用於遷移的 “一體化” Drupal 程序，而把 bug 修復推到以後。</p><p>Lush 12 月 1 日開始物理遷移，12 月 22 日完成。</p><p>團隊“像其他遷移一樣”遇到了挑戰，Constantine 説：“你肯定會擔心將數據從一個地方傳輸到另一個地方，你必須確保一致性，客户、產品數據等需要穩定。”</p><p>但是，這位 CDO 表示，讓公司採用這個難以置信的緊張時間表是因為團隊缺乏備選方案: 沒有後備計劃。</p><p>Constantine 説：“在截止日期前的一個星期，我的同事和我們的 Google 合作伙伴打了電話，他們對這是否會發生有點緊張，他們問我們 Plan B 是什麼，我的同事説：Plan B 就是讓 Plan A，就是這樣”。</p><p>“當你拋出這樣一個聽起來有點難以置信的艱難的截止日期時，而（你需要保持）關注那些認為這是我們可在這個時間範圍內可以實現的目標的人，而不是那些放置阻礙説‘我們必須要延期’的人。”</p><p>“是的，每個人都很緊張，但你實現了很多。你實際上完成並盯牢了它。你所要做的就是完成、完成。”</p><p>現在的重點是將該電子商務應用轉移到微服務架構，同時研究各種 Google 工具，如 Kubernetes 容器管理系統和 Spanner 關係資料庫。</p><p>Constantine 説，該零售商最近也建立了使用 GCP 和 Android 的原型 POS 系統。</p><p>（題圖：Lush&#39;s Oxford St, UK store. Credit: Lush）</p><hr>",14)),s("p",null,[t[4]||(t[4]=p("via: ",-1)),e(o,{href:"https://www.itnews.com.au/news/a-public-cloud-migration-in-22-days-454186"},{default:n(()=>[...t[3]||(t[3]=[p("https://www.itnews.com.au/news/a-public-cloud-migration-in-22-days-454186",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=p("作者：",-1)),e(o,{href:"https://www.itnews.com.au/author/allie-coyne-461593"},{default:n(()=>[...t[5]||(t[5]=[p("Allie Coyne",-1)])]),_:1}),t[9]||(t[9]=p(" 譯者：",-1)),e(o,{href:"https://github.com/geekpi"},{default:n(()=>[...t[6]||(t[6]=[p("geekpi",-1)])]),_:1}),t[10]||(t[10]=p(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[7]||(t[7]=[p("wxy",-1)])]),_:1})]),s("p",null,[t[13]||(t[13]=p("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[11]||(t[11]=[p("LCTT",-1)])]),_:1}),t[14]||(t[14]=p(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:n(()=>[...t[12]||(t[12]=[p("Linux中國",-1)])]),_:1}),t[15]||(t[15]=p(" 榮譽推出",-1))])])}const _=a(d,[["render",m]]);export{A as __pageData,_ as default};
